function solve({config,state,event}) {
  const empty=()=>({id:null,len:0,b:[]});
  let s=state&&typeof state==='object'&&Array.isArray(state.b)?state:empty();
  const count=()=>s.b.reduce((n,x)=>n+(x!==null),0);
  const out=(status,data=null)=>({status,id:s.id,received:count(),data});
  const integer=x=>typeof x==='number'&&Number.isInteger(x)&&Number.isSafeInteger(x);
  if(!event||typeof event!=='object'||typeof event.type!=='string')return {state:s,output:out('invalid')};
  if(event.type==='begin'){
    const m=config&&config.maxLength;
    if(!integer(event.length)||!integer(m)||event.length<0||event.length>m)return {state:s,output:out('invalid')};
    if(s.id!==null&&s.id===event.id){
      if(s.len!==event.length)return {state:s,output:out('conflict')};
      return {state:s,output:out('ok')};
    }
    s={id:event.id,len:event.length,b:Array(event.length).fill(null)};
    return {state:s,output:out('ok')};
  }
  if(event.type==='chunk'){
    if(s.id===null||s.id!==event.id)return {state:s,output:out('ignored')};
    const a=event.bytes;
    let sum=0,ok=Array.isArray(a)&&integer(event.offset)&&event.offset>=0&&integer(event.checksum);
    if(ok)for(const x of a){if(!integer(x)||x<0||x>255){ok=false;break}sum+=x;}
    if(!ok||event.offset+a.length>s.len||sum%251!==event.checksum)return {state:s,output:out('invalid')};
    for(let i=0;i<a.length;i++)if(s.b[event.offset+i]!==null&&s.b[event.offset+i]!==a[i])return {state:s,output:out('conflict')};
    for(let i=0;i<a.length;i++)s.b[event.offset+i]=a[i];
    return {state:s,output:out('ok')};
  }
  if(event.type==='finish'){
    if(s.id===null||s.id!==event.id)return {state:s,output:out('ignored')};
    if(s.b.some(x=>x===null))return {state:s,output:out('incomplete')};
    return {state:s,output:out('complete',s.b.slice())};
  }
  return {state:s,output:out('invalid')};
}
